import os
from tempfile import gettempdir
import base64

import datetime

from PIL import Image, ImageTk


def set_window_icon(root, name='StartGui'):
    try:
        root.iconbitmap(create_icon_file(name))
    except Exception:
        icon_img = ImageTk.PhotoImage(Image.open(create_icon_png_file('start')))
        root.iconphoto(True, icon_img)
        root._pyanoo_icon = icon_img

def create_icon_file(n='i'):
    ICON_STR = ''
    ICON_BYTES = base64.b64decode(ICON_STR)
    if not os.path.exists(os.path.join(gettempdir(),'PyanoO')):
        os.mkdir(os.path.join(gettempdir(),'PyanoO'))
    ICON_PATH = os.path.join(os.path.join(gettempdir(),'PyanoO'),'pyano_{}.ico'.format(n))
    with open(ICON_PATH,'wb') as icf:
        icf.write(ICON_BYTES)

    return ICON_PATH

def create_icon_png_file(n='i'):
    ICON_PNG_STR = ''
    ICON_PNG_BYTES = base64.b64decode(ICON_PNG_STR)
    if not os.path.exists(os.path.join(gettempdir(),'PyanoO')):
        os.mkdir(os.path.join(gettempdir(),'PyanoO'))
    ICON_PNG_PATH = os.path.join(os.path.join(gettempdir(),'PyanoO'),'pyano_png_{}.png'.format(n))
    with open(ICON_PNG_PATH,'wb') as icf:
        icf.write(ICON_PNG_BYTES)

    return ICON_PNG_PATH

def get_astro():
    month = datetime.datetime.now().strftime("%B").lower()
    day = datetime.datetime.now().day

    astro_sign = None
    if month == 'december':
        astro_sign = '♐' if (day < 22) else '♑'
    elif month == 'january':
        astro_sign = '♑' if (day < 20) else '♒'
    elif month == 'february':
        astro_sign = '♒' if (day < 19) else '♓'
    elif month == 'march':
        astro_sign = '♓' if (day < 21) else '♈'
    elif month == 'april':
        astro_sign = '♈' if (day < 20) else '♉'
    elif month == 'may':
        astro_sign = '♉' if (day < 21) else '♊'
    elif month == 'june':
        astro_sign = '♊' if (day < 21) else '♋'
    elif month == 'july':
        astro_sign = '♋' if (day < 23) else '♌'
    elif month == 'august':
        astro_sign = '♌' if (day < 23) else '♍'
    elif month == 'september':
        astro_sign = '♍' if (day < 23) else '♎'
    elif month == 'october':
        astro_sign = '♎' if (day < 23) else '♏'
    elif month == 'november':
        astro_sign = '♏' if (day < 22) else '♐'

    if not astro_sign:
        astro_sign = '⛎'

    return astro_sign